all_transactions = transactions + transactions_page2
sent_total = 0.0
received_total = 0.0
for txn in all_transactions:
    if txn['sender']['email'] == 'jo-harr@gmail.com':
        sent_total += txn['amount']
    elif txn['receiver']['email'] == 'jo-harr@gmail.com':
        received_total += txn['amount']
print(f"Sent: {sent_total}, Received: {received_total}")

