# Let's match old songs to song details
def normalize(s):
    return s.strip().lower()

def song_matches_old(song, old_entry):
    # Check title match
    if normalize(song['title']) != normalize(old_entry['title']):
        return False
    # Check all artists from old entry are present in song's artists
    song_artists = {normalize(a['name']) for a in song['artists']}
    old_artists = {normalize(a) for a in old_entry['artists']}
    return old_artists.issubset(song_artists)

matched_song_ids = set()
for old_entry in old_songs_entries:
    for song_id, song in song_details.items():
        if song_matches_old(song, old_entry):
            matched_song_ids.add(song_id)
            print(f"Matched: {old_entry['title']} by {old_entry['artists']} -> song_id {song_id} ({song['title']} by {[a['name'] for a in song['artists']]})")

print(f"\nTotal matched song IDs: {len(matched_song_ids)}")
print(sorted(matched_song_ids))

# Remove matched songs from all playlists that contain them
for pl in playlists:
    pl_id = pl['playlist_id']
    for song_id in matched_song_ids:
        if song_id in pl['song_ids']:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pl_id, song_id=song_id, access_token=spotify_token)
