# Let's search for all 18 archived songs and find their exact song IDs
# We'll match by title and artist name
archived_song_ids = {}

for song in songs_to_archive:
    title = song['title']
    artist = song['artist']
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    # Find exact match: title matches and artist name matches
    match = None
    for r in results:
        if r['title'].lower() == title.lower():
            # Check if any artist matches
            for art in r['artists']:
                if art['name'].lower() == artist.lower():
                    match = r
                    break
            if match:
                break
    if match:
        archived_song_ids[title] = match['song_id']
        print(f"Found: {title} by {artist} -> song_id {match['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal found: {len(archived_song_ids)}")

