        if r['title'] == song['title'] and any(a['name'] == song['artist'] for a in r['artists']):
            found = r['song_id']
            break
    if found:
        archive_song_ids.append(found)
        print(f"Found: {song['title']} by {song['artist']} -> song_id {found}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")
print("All archive song IDs:", archive_song_ids)

# Remove archived songs from all existing playlists
archive_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
print("Song IDs to archive:", archive_song_ids)

for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    for song_id in playlist["song_ids"]:
        if song_id in archive_song_ids:
            result = apis.spotify.remove_song_from_playlist(
                playlist_id=playlist_id,
                song_id=song_id,
                access_token=login_result["access_token"]
            )
            print(f"Removed song {song_id} from playlist {playlist_id}: {result}")

