# Parse the old songs list into (title, artist) pairs
old_songs = []
for line in file_data['content'].split('\n'):
    line = line.strip()
    if line.startswith('- '):
        song_part = line[2:]
        if ' by ' in song_part:
            title, artists = song_part.split(' by ', 1)
            old_songs.append((title.strip(), artists.strip()))
print(old_songs)

