playlist_song_map = {}
for pl in playlists:
    pl_id = pl['playlist_id']
    details = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_token)
    song_ids = details.get('song_ids', [])
    playlist_song_map[pl_id] = song_ids
    print(f"Playlist {pl_id} ({pl['title']}) has {len(song_ids)} songs")

# Find which playlists contain any target song
containing = {pl_id: [sid for sid in song_ids if sid in target_ids] for pl_id, song_ids in playlist_song_map.items()}
