# Verify all 13 target songs are in playlist 654 and none remain in original playlists
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}

# Get playlist 654 contents
playlist_654 = apis.spotify.show_playlist(playlist_id=654, access_token=spotify_token)
songs_in_654 = {song['id'] for song in playlist_654['songs']}
print("Songs in 654:", songs_in_654)
print("Missing from 654:", target_song_ids - songs_in_654)

# Check all original playlists (513-519) for any target songs
for pid in range(513, 520):
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    song_ids = {song['id'] for song in pl['songs']}
    overlap = song_ids & target_song_ids
    if overlap:
        print(f"Playlist {pid} still contains target songs: {overlap}")
    else:
        print(f"Playlist {pid} clean")

